CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// ConvTranspose2d weight layout: [in_channels, out_channels, kH, kW]
// Output: (N, C_out, H+kH-1, W+kW-1) for stride=1, padding=0
// Each output element: out[n,oc,oh,ow] = sum_{ic,kh,kw} input[n,ic,oh-kh,ow-kw] * weight[ic,oc,kh,kw]
// where (oh-kh) and (ow-kw) are valid input coords.

#define KH 3
#define KW 7
#define C_IN 64
#define C_OUT 64
#define TILE_H 8
#define TILE_W 16

__global__ void conv_transpose2d_3x7_kernel(
    const float* __restrict__ input,   // [N, C_IN, H, W]
    const float* __restrict__ weight,  // [C_IN, C_OUT, KH, KW]
    float* __restrict__ output,        // [N, C_OUT, H+KH-1, W+KW-1]
    int N, int H, int W,
    int outH, int outW
) {
    // blockIdx.x -> tile over outW
    // blockIdx.y -> tile over outH
    // blockIdx.z -> n * C_OUT + oc
    int ow_base = blockIdx.x * TILE_W + threadIdx.x;
    int oh_base = blockIdx.y * TILE_H + threadIdx.y;
    int noc = blockIdx.z;
    int n = noc / C_OUT;
    int oc = noc % C_OUT;

    if (ow_base >= outW || oh_base >= outH) return;
    int oh = oh_base;
    int ow = ow_base;

    float acc = 0.0f;

    const float* inp = input + n * C_IN * H * W;
    // weight[ic, oc, kh, kw] -> ic*(C_OUT*KH*KW) + oc*(KH*KW) + kh*KW + kw
    const float* wt_base = weight + oc * (KH * KW); // per ic: +ic*C_OUT*KH*KW

    #pragma unroll 1
    for (int ic = 0; ic < C_IN; ic++) {
        const float* inp_ic = inp + ic * H * W;
        const float* wt_ic = wt_base + ic * (C_OUT * KH * KW);
        #pragma unroll
        for (int kh = 0; kh < KH; kh++) {
            int ih = oh - kh;
            if (ih < 0 || ih >= H) continue;
            const float* inp_row = inp_ic + ih * W;
            const float* wt_row = wt_ic + kh * KW;
            #pragma unroll
            for (int kw = 0; kw < KW; kw++) {
                int iw = ow - kw;
                if (iw < 0 || iw >= W) continue;
                acc += inp_row[iw] * wt_row[kw];
            }
        }
    }

    output[n * (C_OUT * outH * outW) + oc * (outH * outW) + oh * outW + ow] = acc;
}

torch::Tensor conv_transpose2d_3x7_cuda(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    int N = input.size(0);
    int H = input.size(2);
    int W = input.size(3);
    int outH = H + KH - 1;
    int outW = W + KW - 1;

    auto output = torch::zeros({N, C_OUT, outH, outW}, input.options());

    dim3 block(TILE_W, TILE_H, 1);
    dim3 grid(
        (outW + TILE_W - 1) / TILE_W,
        (outH + TILE_H - 1) / TILE_H,
        N * C_OUT
    );

    conv_transpose2d_3x7_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, H, W, outH, outW
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a transposed 2D convolution with a square input and an asymmetric kernel.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (tuple): Size of the convolution kernel (height, width).
            stride (int, optional): Stride of the convolution. Defaults to 1.
            padding (int or tuple, optional): Padding applied to the input. Defaults to 0.
            output_padding (int or tuple, optional): Additional size added to one side of the output shape. Defaults to 0.
            groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose2d = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding, groups=groups, bias=bias)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs the transposed 2D convolution.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, out_channels, height_out, width_out).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        w = self.conv_transpose2d.weight
                if (x.is_cuda and x.dtype == torch.float32 and x.dim() == 4 and
